"use strict";(globalThis.webpackChunkp_vs_np_docs=globalThis.webpackChunkp_vs_np_docs||[]).push([[2212],{97576(e){e.exports=JSON.parse('{"tag":{"label":"graph-theory","permalink":"/azeon/p-vs-np/tags/graph-theory","allTagsPath":"/azeon/p-vs-np/tags","count":4,"items":[{"id":"np-completeness/hamiltonian-cycle","title":"Hamiltonian Cycle","description":"Visit every city exactly once and come home. It started as a Victorian puzzle game, and it has a twin about roads instead of cities that is easy. Why one is easy and the other is NP-Complete is the real lesson.","permalink":"/azeon/p-vs-np/np-completeness/hamiltonian-cycle"},{"id":"np-completeness/the-clique-problem","title":"The Clique Problem","description":"What does finding mutual friends in a social network have to do with Boolean logic? The reduction from 3-SAT to Clique is the bridge, and it is one of the most satisfying constructions in all of NP-Completeness.","permalink":"/azeon/p-vs-np/np-completeness/the-clique-problem"},{"id":"np-completeness/independent-set","title":"The Independent Set Problem","description":"I have used Independent Set as a stepping stone twice without ever proving it is hard. Today I pay that debt, once the lazy way and once the honest way, straight from 3-SAT.","permalink":"/azeon/p-vs-np/np-completeness/independent-set"},{"id":"np-completeness/vertex-cover","title":"The Vertex Cover Problem","description":"Back in Post 11 I used cameras on roads to explain what a reduction is. I never proved that problem was NP-Complete. Today I finally do, and it takes almost no new work.","permalink":"/azeon/p-vs-np/np-completeness/vertex-cover"}],"unlisted":false}}')}}]);